export interface ShellState {
  readonly busy: boolean;
  readonly panelVisible: boolean;
}

export const START_BUSY = "START_BUSY" as const;
export const STOP_BUSY = "STOP_BUSY" as const;
export const OPEN_PANEL = "OPEN_PANEL" as const;
export const CLOSE_PANEL = "CLOSE_PANEL" as const;

export type StartBusyAction = { readonly type: typeof START_BUSY };
export type StopBusyAction = { readonly type: typeof STOP_BUSY };
export type OpenPanelAction = { readonly type: typeof OPEN_PANEL };
export type ClosePanelAction = { readonly type: typeof CLOSE_PANEL };
export type ShellAction =
  | StartBusyAction
  | StopBusyAction
  | OpenPanelAction
  | ClosePanelAction;

export const initialShellState: ShellState = {
  busy: false,
  panelVisible: false,
};

export const startBusy = (): StartBusyAction => ({ type: START_BUSY });
export const stopBusy = (): StopBusyAction => ({ type: STOP_BUSY });
export const openPanel = (): OpenPanelAction => ({ type: OPEN_PANEL });
export const closePanel = (): ClosePanelAction => ({ type: CLOSE_PANEL });

export function shellReducer(
  state: ShellState = initialShellState,
  action: ShellAction,
): ShellState {
  switch (action.type) {
    case START_BUSY:
      return state.busy ? state : { ...state, busy: true };
    case STOP_BUSY:
      return state.busy ? { ...state, busy: false } : state;
    case OPEN_PANEL:
      return state.panelVisible ? state : { ...state, panelVisible: true };
    case CLOSE_PANEL:
      return state.panelVisible ? { ...state, busy: false } : state;
    default:
      return state;
  }
}

export const selectBusy = (state: ShellState): boolean => state.busy;
export const selectPanelVisible = (state: ShellState): boolean => state.panelVisible;
