import {
  CLOSE_PANEL,
  OPEN_PANEL,
  START_BUSY,
  STOP_BUSY,
  ShellAction,
  ShellState,
  closePanel,
  initialShellState,
  openPanel,
  selectBusy,
  selectPanelVisible,
  shellReducer,
  startBusy,
  stopBusy,
} from './solution';

function assert(condition: boolean, message: string): void {
  if (!condition) throw new Error(message);
}
function equal<T>(actual: T, expected: T, message: string): void {
  if (!Object.is(actual, expected)) throw new Error(`${message}: expected ${String(expected)}, got ${String(actual)}`);
}

equal(initialShellState.busy, false, 'initial busy flag is false');
equal(initialShellState.panelVisible, false, 'initial panel flag is false');
equal(startBusy().type, START_BUSY, 'start action creator');
equal(stopBusy().type, STOP_BUSY, 'stop action creator');
equal(openPanel().type, OPEN_PANEL, 'open action creator');
equal(closePanel().type, CLOSE_PANEL, 'close action creator');

const base: ShellState = Object.freeze({ busy: false, panelVisible: false });
const busy = shellReducer(base, startBusy());
assert(busy !== base, 'changing busy allocates state');
equal(busy.busy, true, 'start sets busy');
equal(busy.panelVisible, false, 'start preserves panel flag');
assert(shellReducer(busy, startBusy()) === busy, 'redundant start preserves identity');

const openBusy = shellReducer(busy, openPanel());
equal(openBusy.busy, true, 'open preserves busy flag');
equal(openBusy.panelVisible, true, 'open sets panel flag');
assert(shellReducer(openBusy, openPanel()) === openBusy, 'redundant open preserves identity');

const closedBusy = shellReducer(openBusy, closePanel());
equal(closedBusy.busy, true, 'close preserves busy flag');
equal(closedBusy.panelVisible, false, 'close clears panel flag');
assert(shellReducer(closedBusy, closePanel()) === closedBusy, 'redundant close preserves identity');

const stopped = shellReducer(openBusy, stopBusy());
equal(stopped.busy, false, 'stop clears busy flag');
equal(stopped.panelVisible, true, 'stop preserves panel flag');
assert(shellReducer(stopped, stopBusy()) === stopped, 'redundant stop preserves identity');

const unknown = { type: 'UNKNOWN' } as unknown as ShellAction;
assert(shellReducer(openBusy, unknown) === openBusy, 'unknown runtime action preserves identity');
equal(selectBusy(openBusy), true, 'busy selector returns flag');
equal(selectPanelVisible(openBusy), true, 'panel selector returns flag');
equal(base.busy, false, 'input state is not mutated');
equal(base.panelVisible, false, 'input panel flag is not mutated');

